const icon = (name, cls = '') => `<svg class="icon ${cls}" viewBox="0 0 24 24" aria-hidden="true">${paths[name] || paths.grid}</svg>`;
const avatar = (u, cls = '') => `<span class="avatar ${SECTORS[u?.sector]?.color || ''} ${cls}" aria-hidden="true">${esc(u?.initials || (u?.name || '?').slice(0, 2).toUpperCase())}</span>`;
const badge = status => `<span class="badge ${esc(status)}"><span class="status-dot"></span>${esc(STATUS[status] || status)}</span>`;
const sectorIcon = sector => `<span class="sector-icon ${SECTORS[sector]?.color || ''}">${icon(SECTORS[sector]?.icon || 'help')}</span>`;
const btn = (label, action, symbol = '', cls = 'btn-primary', attrs = '') => `<button class="btn ${cls}" data-action="${action}" ${attrs}>${symbol ? icon(symbol) : ''}${label}</button>`;
const link = (label, path, symbol = '', cls = 'btn-primary') => `<a class="btn ${cls}" href="#${path}">${symbol ? icon(symbol) : ''}${label}</a>`;
const empty = (title, description, cta = '') => `<div class="empty"><span class="sector-icon">${icon('spark')}</span><h2>${title}</h2><p>${description}</p>${cta}</div>`;
